import 'package:camera/camera.dart';
import 'package:image/image.dart' as img;

Future<Uint8List?> convertCameraImageToPngFast(CameraImage cameraImage) async {
  try {
    late img.Image convertedImage;

    switch (cameraImage.format.group) {
      case ImageFormatGroup.yuv420:
        convertedImage = _convertYUV420Fast(cameraImage);
        break;
      case ImageFormatGroup.bgra8888:
        convertedImage = _convertBGRA8888Fast(cameraImage);
        break;
      default:
        return null;
    }

    return Uint8List.fromList(img.encodePng(convertedImage));
  } catch (e) {
    print('Error: $e');
    return null;
  }
}

img.Image _convertYUV420Fast(CameraImage cameraImage) {
  final int width = cameraImage.width;
  final int height = cameraImage.height;

  final img.Image image = img.Image(width: width, height: height);
  final Uint8List yPlane = cameraImage.planes[0].bytes;
  final Uint8List uPlane = cameraImage.planes[1].bytes;
  final Uint8List vPlane = cameraImage.planes[2].bytes;

  int yIndex = 0;
  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      final int uvIndex = (y ~/ 2) * (width ~/ 2) + (x ~/ 2);

      final int yValue = yPlane[yIndex++];
      final int uValue = uPlane[uvIndex] - 128;
      final int vValue = vPlane[uvIndex] - 128;

      // YUV to RGB conversion
      int r = (yValue + 1.370705 * vValue).round().clamp(0, 255);
      int g = (yValue - 0.698001 * vValue - 0.337633 * uValue).round().clamp(0, 255);
      int b = (yValue + 1.732446 * uValue).round().clamp(0, 255);

      image.setPixelRgb(x, y, r, g, b);
    }
  }

  return image;
}

img.Image _convertBGRA8888Fast(CameraImage cameraImage) {
  return img.Image.fromBytes(
    width: cameraImage.width,
    height: cameraImage.height,
    bytes: cameraImage.planes[0].bytes.buffer,
    format: img.Format.uint8,
    numChannels: 4,
  );
}
```

## Usage Example

```dart
import 'dart:io';
import 'package:camera/camera.dart';
import 'package:path_provider/path_provider.dart';

class CameraScreen extends StatefulWidget {
  @override
  _CameraScreenState createState() => _CameraScreenState();
}

class _CameraScreenState extends State<CameraScreen> {
  CameraController? _controller;

  @override
  void initState() {
    super.initState();
    _initCamera();
  }

  Future<void> _initCamera() async {
    final cameras = await availableCameras();
    _controller = CameraController(cameras[0], ResolutionPreset.medium);
    await _controller!.initialize();

    // Start image stream
    _controller!.startImageStream((CameraImage image) async {
      // Convert to PNG when needed
      final pngBytes = await convertCameraImageToPng(image);
      if (pngBytes != null) {
        await _savePngToFile(pngBytes);
      }
    });

    setState(() {});
  }

  Future<void> _savePngToFile(Uint8List pngBytes) async {
    final directory = await getApplicationDocumentsDirectory();
    final file = File('${directory.path}/camera_image_${DateTime.now().millisecondsSinceEpoch}.png');
    await file.writeAsBytes(pngBytes);
    print('PNG saved to: ${file.path}');
  }

  @override
  Widget build(BuildContext context) {
    if (_controller == null || !_controller!.value.isInitialized) {
      return Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    return Scaffold(
      body: CameraPreview(_controller!),
    );
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }
}
```

## Key Points:

1. **Format Support**: The code handles the most common camera image formats (YUV420, BGRA8888, NV21)
2. **Performance**: Method 2 is optimized for better performance
3. **Error Handling**: Includes proper error handling for unsupported formats
4. **Memory Management**: Uses efficient byte manipulation to minimize memory usage

Choose the method that best fits your performance requirements. Method 1 is more comprehensive, while Method 2 focuses on speed for the most common formats.

